// src/lib/types.ts
var TRAIT_ORDER = ["critical", "confidence", "discipline", "engagement"];

// src/lib/analysis.ts
function ranked(percents) {
  return [...TRAIT_ORDER].sort((a, b) => percents[b] - percents[a] || TRAIT_ORDER.indexOf(a) - TRAIT_ORDER.indexOf(b));
}

// src/lib/archetype.ts
function getArchetype(percents) {
  if (Math.max(...Object.values(percents)) - Math.min(...Object.values(percents)) <= 10) return { ...universal };
  const [top1, top2] = ranked(percents);
  const a = archetypes[top1], b = archetypes[top2];
  return { key: `${top1}-${top2}`, name: `${a.animal}-${b.role}`, emoji: a.emoji, description: `${a.animalDescription} ${b.roleDescription}` };
}

// src/lib/aiTypes.ts
var isObject = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

